def background(grid):
    """The most common color in the grid."""
    return Counter(v for row in grid for v in row).most_common(1)[0][0]

def nonbg_cells(grid, bg=None):
    """All (i, j, color) cells whose color differs from the background."""
    if bg is None: bg = background(grid)
    return [(i, j, v) for i, row in enumerate(grid) for j, v in enumerate(row) if v != bg]

def longest_line(cells, grid):
    """The longest run of 2+ adjacent non-background cells in one row or column (the key shape); None if absent."""
    best = None
    for i, j, v in cells:
        if j + 1 < len(grid[0]) and grid[i][j + 1] != grid[i][j] if False else False:
            pass
    return best

def key_line(grid, bg=None):
    """The longest contiguous horizontal or vertical line (length >= 2) of non-background cells, as a list of (i, j, color)."""
    if bg is None: bg = background(grid)
    h, w = len(grid), len(grid[0])
    best = None
    for i in range(h):
        j = 0
        while j < w:
            if grid[i][j] != bg:
                k = j
                while k < w and grid[i][k] != bg: k += 1
                run = [(i, x, grid[i][x]) for x in range(j, k)]
                if len(run) >= 2 and (best is None or len(run) > len(best)): best = run
                j = k
            else: j += 1
    for j in range(w):
        i = 0
        while i < h:
            if grid[i][j] != bg:
                k = i
                while k < h and grid[k][j] != bg: k += 1
                run = [(x, j, grid[x][j]) for x in range(i, k)]
                if len(run) >= 2 and (best is None or len(run) > len(best)): best = run
                i = k
            else: i += 1
    return best

def stamp_line(grid, bg=None):
    """Copy the grid's key line (longest non-bg run) centered onto every other non-bg cell; other such cells removed, key kept."""
    if bg is None: bg = background(grid)
    h, w = len(grid), len(grid[0])
    key = key_line(grid, bg)
    if key is None: return grid
    kset = {(i, j) for i, j, _ in key}
    horiz = key[0][0] == key[1][0]
    mid = key[len(key) // 2]
    offs = [((0, j - mid[1]) if horiz else (i - mid[0], 0)) for i, j, _ in key]
    res = [[bg] * w for _ in range(h)]
    for i, j, v in key: res[i][j] = v
    for i, j, v in nonbg_cells(grid, bg):
        if (i, j) in kset: continue
        for (di, dj), (_, _, c) in zip(offs, key):
            r, cx = i + di, j + dj
            if 0 <= r < h and 0 <= cx < w: res[r][cx] = c
    return res
